{"code": "# The task says TWO adjacent columns have been transposed - this is ONE transposition
# that affects ALL numbers. We need to find a weight and column index that works for ALL 10 numbers.

numbers = [
    "9783541813919",
    "9789466697461",
    "9783980361396",
    "9784476566804",
    "9782795866647",
    "9785950736933",
    "9789766476526",
    "9785911781255",
    "9787284659245",
    "9784148251559"
]

digits_list = [list(map(int, n)) for n in numbers]

# For each weight, find which column pairs work for ALL numbers
for w in range(2, 10):
    # For each possible y (3 to 10), check if it works for all numbers
    for y in range(3, 11):
        all_valid = True
        for idx, digits in enumerate(digits_list):
            sum_val = 0
            for i in range(13):
                if i == y:
                    d = digits[y+1]
                elif i == y+1:
                    d = digits[y]
                else:
                    d = digits[i]
                weight = 1 if i % 2 == 0 else w
                sum_val += d * weight
            if sum_val % 10 != 0:
                all_valid = False
                break
        if all_valid:
            print(f"Weight w={w}, y={y}: ALL 10 numbers valid!")"}
